/// Every dimension, in logical pixels, for one platform and density.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Metrics {
    pub space_0: f32,
    pub space_1: f32,
    pub space_2: f32,
    pub space_3: f32,
    pub space_4: f32,
    pub space_6: f32,
    pub space_8: f32,
    pub space_12: f32,
    pub space_16: f32,
    pub space_24: f32,
    pub rhythm_1: f32,
    pub rhythm_2: f32,
    pub rhythm_3: f32,
    pub rhythm_4: f32,
    pub rhythm_5: f32,
    pub rhythm_10: f32,
    pub radius_sm: f32,
    pub radius_md: f32,
    pub radius_lg: f32,
    pub radius_xl: f32,
    pub radius_2xl: f32,
    pub radius_pill: f32,
    pub size_icon: f32,
    pub size_icon_md: f32,
    pub size_icon_lg: f32,
    pub size_brand: f32,
    pub size_home_art_max: f32,
    pub size_home_art_centered_max: f32,
    pub size_featured_card_min: f32,
    pub size_direction_card_min: f32,
    pub size_dock_tile: f32,
    pub size_dock_icon: f32,
    pub size_dock_max: f32,
    /// A 3 px pip and lane.
    pub mark_pip: f32,
    /// The small dot and its 5 px lane: kickers, the page bar, rails.
    pub mark_dot: f32,
    /// A 9 px node on a time line.
    pub mark_node: f32,
    /// The 15 px dot at a heading's, a rail's or a foot's end.
    pub mark_dot_lg: f32,
    /// The stroke of drawn controls: a menu's bars, a chevron, a disclosure's plus.
    pub mark_stroke: f32,
    pub border_width_none: f32,
    pub border_width_thin: f32,
    pub border_width_medium: f32,
    pub border_width_thick: f32,
    /// Focus outline width (WCAG 2.2 2.4.13: at least a 2 px perimeter).
    pub focus_width: f32,
    /// Space between a control and its focus outline, filled with surface.base.
    pub focus_gap: f32,
    pub size_control_sm: f32,
    pub size_control_md: f32,
    pub size_control_lg: f32,
    pub size_field: f32,
    pub size_target_min: f32,
}

impl Metrics {
    pub const fn resolve(platform: Platform, density: Density) -> &'static Metrics {
        match (platform, density) {
            (Platform::Ios, Density::Comfortable) => &METRICS_IOS_COMFORTABLE,
            (Platform::Ios, Density::Compact) => &METRICS_IOS_COMPACT,
            (Platform::Android, Density::Comfortable) => &METRICS_ANDROID_COMFORTABLE,
            (Platform::Android, Density::Compact) => &METRICS_ANDROID_COMPACT,
            (Platform::Desktop, Density::Comfortable) => &METRICS_DESKTOP_COMFORTABLE,
            (Platform::Desktop, Density::Compact) => &METRICS_DESKTOP_COMPACT,
        }
    }
}

