/// The fonts of a family on a platform, most preferred first.
pub const fn font_stack(family: FontFamily, platform: Platform) -> &'static [&'static str] {
    match (family, platform) {
        (FontFamily::Sans, Platform::Ios) => &["IBM Plex Sans", ".AppleSystemUIFont"],
        (FontFamily::Sans, Platform::Android) => &["IBM Plex Sans", "Roboto"],
        (FontFamily::Sans, Platform::Desktop) => &["IBM Plex Sans", "IBM Plex Sans Fallback", "system-ui", "-apple-system", "Segoe UI", "Roboto", "Helvetica Neue", "Arial", "sans-serif"],
        (FontFamily::SansAr, Platform::Ios) => &["IBM Plex Sans Arabic", ".AppleSystemUIFont"],
        (FontFamily::SansAr, Platform::Android) => &["IBM Plex Sans Arabic", "Noto Sans Arabic"],
        (FontFamily::SansAr, Platform::Desktop) => &["IBM Plex Sans Arabic", "IBM Plex Sans", "IBM Plex Sans Fallback", "system-ui", "Segoe UI", "Tahoma", "Arial", "sans-serif"],
        (FontFamily::SansZh, Platform::Ios) => &["PingFang SC"],
        (FontFamily::SansZh, Platform::Android) => &["Noto Sans CJK SC"],
        (FontFamily::SansZh, Platform::Desktop) => &["IBM Plex Sans", "Noto Sans SC", "IBM Plex Sans Fallback", "system-ui", "PingFang SC", "Microsoft YaHei", "sans-serif"],
        (FontFamily::Mono, Platform::Ios) => &["SF Mono", "Menlo"],
        (FontFamily::Mono, Platform::Android) => &["monospace"],
        (FontFamily::Mono, Platform::Desktop) => &["ui-monospace", "SFMono-Regular", "Menlo", "Consolas", "Liberation Mono", "monospace"],
    }
}

/// Durations.
pub mod durations {
    use super::{Duration, Motion};

    pub const fn duration_ui_fast(motion: Motion) -> Duration {
        match motion {
            Motion::Standard => Duration::from_millis(150),
            Motion::Reduced => Duration::from_millis(0),
        }
    }

    pub const fn duration_ui(motion: Motion) -> Duration {
        match motion {
            Motion::Standard => Duration::from_millis(250),
            Motion::Reduced => Duration::from_millis(0),
        }
    }

    pub const fn duration_scene(motion: Motion) -> Duration {
        match motion {
            Motion::Standard => Duration::from_millis(450),
            Motion::Reduced => Duration::from_millis(0),
        }
    }

    pub const fn duration_scene_slow(motion: Motion) -> Duration {
        match motion {
            Motion::Standard => Duration::from_millis(900),
            Motion::Reduced => Duration::from_millis(0),
        }
    }
}

/// Easings as cubic Bezier control points (x1, y1, x2, y2).
pub mod easings {
    /// The standard easing of interface motion.
    pub const EASING: [f32; 4] = [0.2, 0.7, 0.2, 1.0];
    /// Decelerate: something arriving.
    pub const EASING_ENTER: [f32; 4] = [0.0, 0.0, 0.2, 1.0];
    /// Accelerate: something leaving.
    pub const EASING_EXIT: [f32; 4] = [0.4, 0.0, 1.0, 1.0];
    /// A larger, more noticeable change.
    pub const EASING_EMPHASIZED: [f32; 4] = [0.2, 0.0, 0.0, 1.0];
}

/// One layer of a shadow, in logical pixels.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct ShadowLayer {
    pub color: Color,
    pub x: f32,
    pub y: f32,
    pub blur: f32,
    pub spread: f32,
    pub inset: bool,
}

/// Elevation shadows per theme.
pub mod shadows {
    use super::{Color, ShadowLayer, Theme};

    pub const fn elevation_1(theme: Theme) -> &'static [ShadowLayer] {
        match theme {
            Theme::Light => &[ShadowLayer { color: Color { r: 0x00, g: 0x00, b: 0x00, a: 0x1F }, x: 0.0, y: 1.0, blur: 3.0, spread: 0.0, inset: false }],
            Theme::Dark => &[ShadowLayer { color: Color { r: 0x00, g: 0x00, b: 0x00, a: 0x99 }, x: 0.0, y: 1.0, blur: 2.0, spread: 0.0, inset: false }],
            Theme::LightContrast => &[ShadowLayer { color: Color { r: 0x00, g: 0x00, b: 0x00, a: 0x1F }, x: 0.0, y: 1.0, blur: 3.0, spread: 0.0, inset: false }],
            Theme::DarkContrast => &[ShadowLayer { color: Color { r: 0x00, g: 0x00, b: 0x00, a: 0x99 }, x: 0.0, y: 1.0, blur: 2.0, spread: 0.0, inset: false }],
        }
    }

    pub const fn elevation_2(theme: Theme) -> &'static [ShadowLayer] {
        match theme {
            Theme::Light => &[ShadowLayer { color: Color { r: 0x00, g: 0x00, b: 0x00, a: 0x1F }, x: 0.0, y: 6.0, blur: 16.0, spread: 0.0, inset: false }],
            Theme::Dark => &[ShadowLayer { color: Color { r: 0x00, g: 0x00, b: 0x00, a: 0xB3 }, x: 0.0, y: 4.0, blur: 12.0, spread: 0.0, inset: false }],
            Theme::LightContrast => &[ShadowLayer { color: Color { r: 0x00, g: 0x00, b: 0x00, a: 0x1F }, x: 0.0, y: 6.0, blur: 16.0, spread: 0.0, inset: false }],
            Theme::DarkContrast => &[ShadowLayer { color: Color { r: 0x00, g: 0x00, b: 0x00, a: 0xB3 }, x: 0.0, y: 4.0, blur: 12.0, spread: 0.0, inset: false }],
        }
    }

    pub const fn elevation_3(theme: Theme) -> &'static [ShadowLayer] {
        match theme {
            Theme::Light => &[ShadowLayer { color: Color { r: 0x00, g: 0x00, b: 0x00, a: 0x29 }, x: 0.0, y: 16.0, blur: 40.0, spread: 0.0, inset: false }],
            Theme::Dark => &[ShadowLayer { color: Color { r: 0x00, g: 0x00, b: 0x00, a: 0xCC }, x: 0.0, y: 12.0, blur: 32.0, spread: 0.0, inset: false }],
            Theme::LightContrast => &[ShadowLayer { color: Color { r: 0x00, g: 0x00, b: 0x00, a: 0x29 }, x: 0.0, y: 16.0, blur: 40.0, spread: 0.0, inset: false }],
            Theme::DarkContrast => &[ShadowLayer { color: Color { r: 0x00, g: 0x00, b: 0x00, a: 0xCC }, x: 0.0, y: 12.0, blur: 32.0, spread: 0.0, inset: false }],
        }
    }
}

/// The faces this crate bundles (OFL-1.1, fonts/OFL-IBM-Plex.txt), with the `fonts` feature: the
