/// A text style on a platform: family, size, line height as a multiple of the size, weight, letter
/// spacing as a share of the size (em), case.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct TextStyle {
    pub family: FontFamily,
    pub size: f32,
    pub line_height: f32,
    pub weight: u16,
    pub tracking: f32,
    pub uppercase: bool,
}

impl TextStyle {
    /// The style of a role on a platform, adjusted for the script of the text.
    pub const fn resolve(role: TypeRole, platform: Platform, script: Script) -> TextStyle {
        let base = Self::base(role, platform);
        TextStyle {
            family: if matches!(base.family, FontFamily::Sans) { script.family() } else { base.family },
            size: base.size,
            line_height: match (role.is_body(), script.body_leading()) {
                (true, Some(leading)) => leading,
                _ => base.line_height,
            },
            weight: base.weight,
            tracking: if script.tracks_letters() { base.tracking } else { 0.0 },
            uppercase: script.has_case() && base.uppercase,
        }
    }

    /// Letter spacing in logical pixels.
    pub fn tracking_px(&self) -> f32 {
        self.tracking * self.size
    }

    const fn base(role: TypeRole, platform: Platform) -> TextStyle {
        match (role, platform) {
            (TypeRole::Display, Platform::Ios) => TextStyle { family: FontFamily::Sans, size: 34.0, line_height: 1.06, weight: 400, tracking: -0.02, uppercase: false },
            (TypeRole::Display, Platform::Android) => TextStyle { family: FontFamily::Sans, size: 36.0, line_height: 1.06, weight: 400, tracking: -0.02, uppercase: false },
            (TypeRole::Display, Platform::Desktop) => TextStyle { family: FontFamily::Sans, size: 40.0, line_height: 1.06, weight: 400, tracking: -0.02, uppercase: false },
            (TypeRole::H1, Platform::Ios) => TextStyle { family: FontFamily::Sans, size: 28.0, line_height: 1.1, weight: 400, tracking: -0.01, uppercase: false },
            (TypeRole::H1, Platform::Android) => TextStyle { family: FontFamily::Sans, size: 32.0, line_height: 1.1, weight: 400, tracking: -0.01, uppercase: false },
            (TypeRole::H1, Platform::Desktop) => TextStyle { family: FontFamily::Sans, size: 32.0, line_height: 1.1, weight: 400, tracking: -0.01, uppercase: false },
            (TypeRole::H2, Platform::Ios) => TextStyle { family: FontFamily::Sans, size: 22.0, line_height: 1.15, weight: 400, tracking: -0.01, uppercase: false },
            (TypeRole::H2, Platform::Android) => TextStyle { family: FontFamily::Sans, size: 28.0, line_height: 1.15, weight: 400, tracking: -0.01, uppercase: false },
            (TypeRole::H2, Platform::Desktop) => TextStyle { family: FontFamily::Sans, size: 28.0, line_height: 1.15, weight: 400, tracking: -0.01, uppercase: false },
            (TypeRole::H3, Platform::Ios) => TextStyle { family: FontFamily::Sans, size: 20.0, line_height: 1.22, weight: 400, tracking: -0.01, uppercase: false },
            (TypeRole::H3, Platform::Android) => TextStyle { family: FontFamily::Sans, size: 24.0, line_height: 1.22, weight: 400, tracking: -0.01, uppercase: false },
            (TypeRole::H3, Platform::Desktop) => TextStyle { family: FontFamily::Sans, size: 22.0, line_height: 1.22, weight: 400, tracking: -0.01, uppercase: false },
            (TypeRole::H4, Platform::Ios) => TextStyle { family: FontFamily::Sans, size: 17.0, line_height: 1.3, weight: 400, tracking: -0.01, uppercase: false },
            (TypeRole::H4, Platform::Android) => TextStyle { family: FontFamily::Sans, size: 22.0, line_height: 1.3, weight: 400, tracking: -0.01, uppercase: false },
            (TypeRole::H4, Platform::Desktop) => TextStyle { family: FontFamily::Sans, size: 18.0, line_height: 1.3, weight: 400, tracking: -0.01, uppercase: false },
            (TypeRole::Lead, Platform::Ios) => TextStyle { family: FontFamily::Sans, size: 17.0, line_height: 1.55, weight: 400, tracking: 0.0, uppercase: false },
            (TypeRole::Lead, Platform::Android) => TextStyle { family: FontFamily::Sans, size: 16.0, line_height: 1.55, weight: 400, tracking: 0.0, uppercase: false },
            (TypeRole::Lead, Platform::Desktop) => TextStyle { family: FontFamily::Sans, size: 16.0, line_height: 1.55, weight: 400, tracking: 0.0, uppercase: false },
            (TypeRole::Body, Platform::Ios) => TextStyle { family: FontFamily::Sans, size: 16.0, line_height: 1.6, weight: 400, tracking: 0.0, uppercase: false },
            (TypeRole::Body, Platform::Android) => TextStyle { family: FontFamily::Sans, size: 14.0, line_height: 1.6, weight: 400, tracking: 0.0, uppercase: false },
            (TypeRole::Body, Platform::Desktop) => TextStyle { family: FontFamily::Sans, size: 14.0, line_height: 1.6, weight: 400, tracking: 0.0, uppercase: false },
            (TypeRole::Label, Platform::Ios) => TextStyle { family: FontFamily::Sans, size: 15.0, line_height: 1.4, weight: 400, tracking: 0.0, uppercase: false },
            (TypeRole::Label, Platform::Android) => TextStyle { family: FontFamily::Sans, size: 14.0, line_height: 1.4, weight: 400, tracking: 0.0, uppercase: false },
            (TypeRole::Label, Platform::Desktop) => TextStyle { family: FontFamily::Sans, size: 13.0, line_height: 1.4, weight: 400, tracking: 0.0, uppercase: false },
            (TypeRole::Kicker, Platform::Ios) => TextStyle { family: FontFamily::Sans, size: 15.0, line_height: 1.4, weight: 400, tracking: 0.06, uppercase: true },
            (TypeRole::Kicker, Platform::Android) => TextStyle { family: FontFamily::Sans, size: 14.0, line_height: 1.4, weight: 400, tracking: 0.06, uppercase: true },
            (TypeRole::Kicker, Platform::Desktop) => TextStyle { family: FontFamily::Sans, size: 13.0, line_height: 1.4, weight: 400, tracking: 0.06, uppercase: true },
            (TypeRole::Caption, Platform::Ios) => TextStyle { family: FontFamily::Sans, size: 12.0, line_height: 1.3, weight: 400, tracking: 0.0, uppercase: false },
            (TypeRole::Caption, Platform::Android) => TextStyle { family: FontFamily::Sans, size: 12.0, line_height: 1.3, weight: 400, tracking: 0.0, uppercase: false },
            (TypeRole::Caption, Platform::Desktop) => TextStyle { family: FontFamily::Sans, size: 12.0, line_height: 1.3, weight: 400, tracking: 0.0, uppercase: false },
            (TypeRole::Code, Platform::Ios) => TextStyle { family: FontFamily::Mono, size: 15.2, line_height: 1.6, weight: 400, tracking: 0.0, uppercase: false },
            (TypeRole::Code, Platform::Android) => TextStyle { family: FontFamily::Mono, size: 13.3, line_height: 1.6, weight: 400, tracking: 0.0, uppercase: false },
            (TypeRole::Code, Platform::Desktop) => TextStyle { family: FontFamily::Mono, size: 13.3, line_height: 1.6, weight: 400, tracking: 0.0, uppercase: false },
        }
    }
}

